        if (p == null || p.length < 2) {
            continue;
        }
        int a = p[0];
        int b = p[1];
        if (a < 0 || a >= n || b < 0 || b >= n) {
            continue;
        }
        adj.get(a).add(b);
        adj.get(b).add(a);
    }
    if (startIdx == endIdx) {
        return "can be travelled";
    }
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.add(startIdx);
    visited[startIdx] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int neighbor : adj.get(cur)) {
            if (!visited[neighbor]) {
                if (neighbor == endIdx) {
