public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int prevPrev = cost[0];
    int prev = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev, prevPrev);
        prevPrev = prev;
        prev = curr;
    }
    return Math.min(prev, prevPrev);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null) {
        return 0;
    }
    // Morse code mapping for letters 'a' to 'z'
    final String[] morse = {".-","-...","-.-.","-..",".","..-.",
                            "--.","....","..",".---","-.-",".-..",
                            "--",".-.", "...","-","..-","...-",
                            ".--","-..-","-.--","--.."};
    Set<String> unique = new HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue; // skip null entries
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') { // handle uppercase just in case
                sb.append(morse[c - 'A']);
            } else {
                // For unsupported characters, we can skip or throw an exception.
                // Here we skip to avoid breaking entire process.
                continue;
            }
        }
        unique.add(sb.toString());
    }
    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string s must not be null.");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Parameter k must be positive.");
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int totalCodes = 1 << k;
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int value = 0;
    // Build the first k bits
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    seen[value] = true;
    int count = 1;
    for (int i = k; i < n; i++) {
        value = ((value << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == totalCodes) {
                return true;
            }
        }
    }
    return count == totalCodes;
}

