public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // open brackets that need closing
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--; // match with a previous '('
            } else {
                // need an extra '(' before this ')'
                insertions++;
            }
        } else {
            // unsupported character; according to spec this should not happen
            throw new IllegalArgumentException("String contains invalid character: " + c);
        }
    }
    // Any remaining unmatched '(' require ')' insertions
    insertions += balance;
    return insertions;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long ops;
    if ((n & 1) == 0) { // n is even
        long k = n / 2L;
        ops = k * k;
    } else { // n is odd
        long k = (n - 1) / 2L;
        ops = k * (k + 1);
    }
    if (ops > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds integer range");
    }
    return (int) ops;
}

