    List<Integer> factors = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    Collections.sort(factors);
    if (factors.size() < k) return -1;
    return factors.get(k - 1);
}

