    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Character.toLowerCase(last) == Character.toLowerCase(c) && last != c) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    return dfs(s, 0, new java.util.HashSet<String>());
}

private int dfs(String s, int index, java.util.Set<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = 1 + dfs(s, end, used);
            if (res > max) {
                max = res;
            }
            used.remove(sub);
        }
    }
    return max;
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // stay in the current folder
                break;
            default:
                // any other string represents a move into a subfolder
                depth++;
                break;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input: length must be positive and value must be achievable
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }
    char[] result = new char[n];
    // Initially fill with 'a' (value 1)
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // additional value to distribute
    // Distribute the remaining value starting from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase at most 25 (from 'a' to 'z')
        result[i] = (char)(result[i] + add);
        remaining -= add;
    }
    return new String(result);
}

