public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if (((num >>> i) & 1) == 1) {
                bitCount[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high || high < 0) {
        return result; // empty list for invalid range
    }
    Queue<Long> queue = new LinkedList<>();
    // Start with digits 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (num == 0) { // handle leading zero: only allow next digit 1 to keep number non-zero
            long child = num * 10 + 1;
            if (child <= high) {
                queue.offer(child);
            }
            continue;
        }
        if (lastDigit > 0) {
            long child = num * 10 + (lastDigit - 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
        if (lastDigit < 9) {
            long child = num * 10 + (lastDigit + 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower   = n % factor;
        long cur     = (n / factor) % 10;
        long higher  = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        if (factor > Long.MAX_VALUE / 10) { // prevent overflow in next iteration
            break;
        }
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // Only positive integers can be powers of two
    if (n <= 0) {
        return false;
    }
    // A number n is a power of two if it has exactly one bit set.
    // This holds true when n & (n - 1) == 0.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
