public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int best = 0;
    // dp[i][j][d] where d=0 horizontal,1 vertical,2 diagonal,3 anti-diagonal
    int[][][] dp = new int[m][n][4];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j-1][0] : 0) + 1;
                dp[i][j][1] = (i > 0 ? dp[i-1][j][1] : 0) + 1;
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i-1][j-1][2] : 0) + 1;
                dp[i][j][3] = (i > 0 && j < n-1 ? dp[i-1][j+1][3] : 0) + 1;
                best = Math.max(best,
                        Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                 Math.max(dp[i][j][2], dp[i][j][3])));
            }
        }
    }
    return best;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    int absValue = Math.abs(n);
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (absValue > 0) {
        sb.append(absValue % 10);
        absValue /= 10;
        digitCount++;
        if (absValue > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute a set of perfect squares up to the maximum possible sum
    int maxVal = 0;
    for (int num : A) {
        if (num > maxVal) maxVal = num;
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; (long)i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    int[][] dp = new int[n][1 << n];
    for (int i = 0; i < n; i++) {
        dp[i][1 << i] = 1;
    }

    for (int mask = 1; mask < (1 << n); mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0) continue;
            int currentCount = dp[last][mask];
            if (currentCount == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                int sum = A[last] + A[next];
                if (isSquare[sum]) {
                    int newMask = mask | (1 << next);
                    dp[next][newMask] += currentCount;
                }
            }
        }
    }

    int fullMask = (1 << n) - 1;
    int total = 0;
    for (int last = 0; last < n; last++) {
        total += dp[last][fullMask];
    }
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && curHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = top == -1 ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        int startRow = Math.max(0, d - n + 1);
        int endRow = Math.min(d, m - 1);
        if (d % 2 == 0) {
            for (int r = endRow; r >= startRow; r--) {
                int c = d - r;
                if (c >= 0 && c < n) {
                    result[idx++] = mat[r][c];
                }
            }
        } else {
            for (int r = startRow; r <= endRow; r++) {
                int c = d - r;
                if (c >= 0 && c < n) {
                    result[idx++] = mat[r][c];
                }
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    String s = Integer.toString(n);
    if (s.length() == 1) {
        return -1;
    }
    char[] digits = s.toCharArray();

    // Find the longest non-increasing suffix and find the pivot
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // digits are in descending order – no larger permutation
        return -1;
    }

    // Find rightmost successor to pivot
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap pivot with successor
    char tmp = digits[i];
    digits[i] = digits[j];
    digits[j] = tmp;

    // Reverse the suffix starting at i+1
    int l = i + 1, r = digits.length - 1;
    while (l < r) {
        tmp = digits[l];
        digits[l] = digits[r];
        digits[r] = tmp;
        l++;
        r--;
    }

    // Convert back to number, handling potential overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }

    return (int) result;
}

