public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The position must be a positive integer.");
    }
    long[] ugly = new long[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return (int) ugly[n - 1];
}

